/** Source: pokemon_storage_system.c → Task_PCMainMenu */
export const Task_PCMainMenu: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  /* task already param */
      switch (task.data[0])
      {
      case STATE_LOAD:
          CreateMainMenu(task.data[1], task.data[15]);
          LoadMessageBoxAndBorderGfx();
          DrawDialogueFrame(0, false);
          FillWindowPixelBuffer(0, PIXEL_FILL(1));
          AddTextPrinterParameterized2(0, FONT_NORMAL, sMainMenuTexts[task.data[1]].desc, TEXT_SKIP_DRAW, null, TEXT_COLOR_DARK_GRAY, TEXT_COLOR_WHITE, TEXT_COLOR_LIGHT_GRAY);
          CopyWindowToVram(0, COPYWIN_FULL);
          CopyWindowToVram(task.data[15], COPYWIN_FULL);
          task.data[0]++;
          break;
      case STATE_FADE_IN:
          if (IsWeatherNotFadingIn())
              task.data[0]++;
          break;
      case STATE_HANDLE_INPUT:
          task.data[2] = Menu_ProcessInput();
          switch(task.data[2])
          {
          case MENU_NOTHING_CHOSEN:
              task.data[3] = task.data[1];
              if (JOY_NEW(DPAD_UP) && --task.data[3] < 0)
                  task.data[3] = OPTIONS_COUNT - 1;
              if (JOY_NEW(DPAD_DOWN) && ++task.data[3] > OPTIONS_COUNT - 1)
                  task.data[3] = 0;

              if (task.data[1] != task.data[3])
              {
                  task.data[1] = task.data[3];
                  FillWindowPixelBuffer(0, PIXEL_FILL(1));
                  AddTextPrinterParameterized2(0, FONT_NORMAL, sMainMenuTexts[task.data[1]].desc, 0, null, TEXT_COLOR_DARK_GRAY, TEXT_COLOR_WHITE, TEXT_COLOR_LIGHT_GRAY);
              }
              break;
          case MENU_B_PRESSED:
          case OPTION_EXIT:
              ClearStdWindowAndFrame(task.data[15], true);
              UnlockPlayerFieldControls();
              ScriptContext_Enable();
              RemoveWindow(task.data[15]);
              rt.DestroyTask(taskId);
              break;
          default:
              if (task.data[2] == OPTION_WITHDRAW && CountPartyMons() == PARTY_SIZE)
              {
                   
                  FillWindowPixelBuffer(0, PIXEL_FILL(1));
                  AddTextPrinterParameterized2(0, FONT_NORMAL, gText_PartyFull, 0, null, TEXT_COLOR_DARK_GRAY, TEXT_COLOR_WHITE, TEXT_COLOR_LIGHT_GRAY);
                  task.data[0] = STATE_ERROR_MSG;
              }
              else if (task.data[2] == OPTION_DEPOSIT && CountPartyMons() == 1)
              {
                   
                  FillWindowPixelBuffer(0, PIXEL_FILL(1));
                  AddTextPrinterParameterized2(0, FONT_NORMAL, gText_JustOnePkmn, 0, null, TEXT_COLOR_DARK_GRAY, TEXT_COLOR_WHITE, TEXT_COLOR_LIGHT_GRAY);
                  task.data[0] = STATE_ERROR_MSG;
              }
              else
              {
                   
                  FadeScreen(FADE_TO_BLACK, 0);
                  task.data[0] = STATE_ENTER_PC;
              }
              break;
          }
          break;
      case STATE_ERROR_MSG:
           
           
          if (JOY_NEW(A_BUTTON | B_BUTTON))
          {
              FillWindowPixelBuffer(0, PIXEL_FILL(1));
              AddTextPrinterParameterized2(0, FONT_NORMAL, sMainMenuTexts[task.data[1]].desc, 0, null, TEXT_COLOR_DARK_GRAY, TEXT_COLOR_WHITE, TEXT_COLOR_LIGHT_GRAY);
              task.data[0] = STATE_HANDLE_INPUT;
          }
          else if (JOY_NEW(DPAD_UP))
          {
              if (--task.data[1] < 0)
                  task.data[1] = OPTIONS_COUNT - 1;
              Menu_MoveCursor(-1);
              task.data[1] = Menu_GetCursorPos();
              FillWindowPixelBuffer(0, PIXEL_FILL(1));
              AddTextPrinterParameterized2(0, FONT_NORMAL, sMainMenuTexts[task.data[1]].desc, 0, null, TEXT_COLOR_DARK_GRAY, TEXT_COLOR_WHITE, TEXT_COLOR_LIGHT_GRAY);
              task.data[0] = STATE_HANDLE_INPUT;
          }
          else if (JOY_NEW(DPAD_DOWN))
          {
              if (++task.data[1] >= OPTIONS_COUNT - 1)
                  task.data[1] = 0;
              Menu_MoveCursor(1);
              task.data[1] = Menu_GetCursorPos();
              FillWindowPixelBuffer(0, PIXEL_FILL(1));
              AddTextPrinterParameterized2(0, FONT_NORMAL, sMainMenuTexts[task.data[1]].desc, 0, null, TEXT_COLOR_DARK_GRAY, TEXT_COLOR_WHITE, TEXT_COLOR_LIGHT_GRAY);
              task.data[0] = STATE_HANDLE_INPUT;
          }
          break;
      case STATE_ENTER_PC:
          if (!rt.gPaletteFade.active)
          {
              CleanupOverworldWindowsAndTilemaps();
              EnterPokeStorage(task.data[2]);
              RemoveWindow(task.data[15]);
              rt.DestroyTask(taskId);
          }
          break;
      }
};

/** Source: pokemon_storage_system.c → Task_InitPokeStorage */
export const Task_InitPokeStorage: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  switch (sStorage.state)
      {
      case 0:
          rt.SetVBlankCallback(VBlankCB);
          rt.SetGpuReg(REG_OFFSET_DISPCNT, 0);
          ResetForPokeStorage();
          if (sStorage.isReopening)
          {
              switch (sWhichToReshow)
              {
              case SCREEN_CHANGE_NAME_BOX - 1:
                   
                  LoadSavedMovingMon();
                  break;
              case SCREEN_CHANGE_SUMMARY_SCREEN - 1:
                   
                  SetSelectionAfterSummaryScreen();
                  break;
              case SCREEN_CHANGE_ITEM_FROM_BAG - 1:
                   
                  GiveChosenBagItem();
                  break;
              }
          }
          LoadPokeStorageMenuGfx();
          LoadWaveformSpritePalette();
          break;
      case 1:
          if (!InitPokeStorageWindows())
          {
              SetPokeStorageTask(Task_ChangeScreen);
              return;
          }
          break;
      case 2:
          PutWindowTilemap(WIN_DISPLAY_INFO);
          ClearWindowTilemap(WIN_MESSAGE);
          CpuFill32(0, VRAM, 0x200);
          LoadUserWindowBorderGfx(WIN_MESSAGE, 0xB, BG_PLTT_ID(14));
          break;
      case 3:
          ResetAllBgCoords();
          if (!sStorage.isReopening)
              InitStartingPosData();
          break;
      case 4:
          InitMonIconFields();
          if (!sStorage.isReopening)
              InitCursor();
          else
              InitCursorOnReopen();
          break;
      case 5:
          if (!MultiMove_Init())
          {
              SetPokeStorageTask(Task_ChangeScreen);
              return;
          }
          else
          {
              SetScrollingBackground();
              InitPokeStorageBg0();
          }
          break;
      case 6:
          InitPalettesAndSprites();
          break;
      case 7:
          InitSupplementalTilemaps();
          break;
      case 8:
          CreateInitBoxTask(StorageGetCurrentBox());
          break;
      case 9:
          if (IsInitBoxActive())
              return;

          if (sStorage.boxOption != OPTION_MOVE_ITEMS)
          {
              sStorage.markMenu.baseTileTag = GFXTAG_MARKING_MENU;
              sStorage.markMenu.basePaletteTag = PALTAG_MARKING_MENU;
              InitMonMarkingsMenu(sStorage.markMenu);
              BufferMonMarkingsMenuTiles();
          }
          else
          {
              CreateItemIconSprites();
              InitCursorItemIcon();
          }
          break;
      case 10:
          SetMonIconTransparency();
          if (!sStorage.isReopening)
          {
              BlendPalettes(PALETTES_ALL, 16, RGB_BLACK);
              SetPokeStorageTask(Task_ShowPokeStorage);
          }
          else
          {
              BlendPalettes(PALETTES_ALL, 16, RGB_BLACK);
              SetPokeStorageTask(Task_ReshowPokeStorage);
          }
          rt.SetVBlankCallback(VBlankCB);
          return;
      default:
          return;
      }

      sStorage.state++;
};

