/** Source: pokemon_storage_system.c → Task_WithdrawMon */
export const Task_WithdrawMon: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  switch (sStorage.state)
      {
      case 0:
          if (CalculatePlayerPartyCount() == PARTY_SIZE)
          {
              PrintMessage(MSG_PARTY_FULL);
              sStorage.state = 1;
          }
          else
          {
              SaveCursorPos();
              InitMonPlaceChange(CHANGE_GRAB);
              sStorage.state = 2;
          }
          break;
      case 1:
          if (JOY_NEW(A_BUTTON | B_BUTTON | DPAD_ANY))
          {
              ClearBottomWindow();
              SetPokeStorageTask(Task_PokeStorageMain);
          }
          break;
      case 2:
          if (!DoMonPlaceChange())
          {
              SetMovingMonPriority(1);
              SetUpDoShowPartyMenu();
              sStorage.state++;
          }
          break;
      case 3:
          if (!DoShowPartyMenu())
          {
              InitMonPlaceChange(CHANGE_PLACE);
              sStorage.state++;
          }
          break;
      case 4:
          if (!DoMonPlaceChange())
          {
              UpdatePartySlotColors();
              sStorage.state++;
          }
          break;
      case 5:
          SetPokeStorageTask(Task_HidePartyPokemon);
          break;
      }
};

/** Source: pokemon_storage_system.c → Task_DepositMenu */
export const Task_DepositMenu: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let boxId = 0;

      switch (sStorage.state)
      {
      case 0:
          PrintMessage(MSG_DEPOSIT_IN_WHICH_BOX);
          LoadChooseBoxMenuGfx(sStorage.chooseBoxMenu, GFXTAG_CHOOSE_BOX_MENU, PALTAG_MISC_1, 3, false);
          CreateChooseBoxMenuSprites(sDepositBoxId);
          sStorage.state++;
          break;
      case 1:
          boxId = HandleChooseBoxMenuInput();
          switch (boxId)
          {
          case BOXID_NONE_CHOSEN:
              break;
          case BOXID_CANCELED:
              ClearBottomWindow();
              DestroyChooseBoxMenuSprites();
              FreeChooseBoxMenu();
              SetPokeStorageTask(Task_PokeStorageMain);
              break;
          default:
              if (TryStorePartyMonInBox(boxId))
              {
                  sDepositBoxId = boxId;
                  ClearBottomWindow();
                  DestroyChooseBoxMenuSprites();
                  FreeChooseBoxMenu();
                  sStorage.state = 2;
              }
              else
              {
                  PrintMessage(MSG_BOX_IS_FULL);
                  sStorage.state = 4;
              }
              break;
          }
          break;
      case 2:
          CompactPartySlots();
          CompactPartySprites();
          sStorage.state++;
          break;
      case 3:
          if (GetNumPartySpritesCompacting() == 0)
          {
              ResetSelectionAfterDeposit();
              StartDisplayMonMosaicEffect();
              UpdatePartySlotColors();
              SetPokeStorageTask(Task_PokeStorageMain);
          }
          break;
      case 4:
          if (JOY_NEW(A_BUTTON | B_BUTTON | DPAD_ANY))
          {
              PrintMessage(MSG_DEPOSIT_IN_WHICH_BOX);
              sStorage.state = 1;
          }
          break;
      }
};

/** Source: pokemon_storage_system.c → Task_ReleaseMon */
export const Task_ReleaseMon: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  switch (sStorage.state)
      {
      case 0:
          PrintMessage(MSG_RELEASE_POKE);
          ShowYesNoWindow(1);
          sStorage.state++;
           
      case 1:
          switch (Menu_ProcessInputNoWrapClearOnChoose())
          {
          case MENU_B_PRESSED:
          case  1:  
              ClearBottomWindow();
              SetPokeStorageTask(Task_PokeStorageMain);
              break;
          case  0:  
              ClearBottomWindow();
              InitCanReleaseMonVars();
              InitReleaseMon();
              sStorage.state++;
              break;
          }
          break;
      case 2:
          RunCanReleaseMon();
          if (!TryHideReleaseMon())
          {
              while (1)
              {
                  let canRelease = RunCanReleaseMon();
                  if (canRelease == true)
                  {
                      sStorage.state++;
                      break;
                  }
                  else if (!canRelease)
                  {
                      sStorage.state = 8;
                      break;
                  }
              }
          }
          break;
      case 3:
          ReleaseMon();
          RefreshDisplayMonData();
          PrintMessage(MSG_WAS_RELEASED);
          sStorage.state++;
          break;
      case 4:
          if (JOY_NEW(A_BUTTON | B_BUTTON | DPAD_ANY))
          {
              PrintMessage(MSG_BYE_BYE);
              sStorage.state++;
          }
          break;
      case 5:
          if (JOY_NEW(A_BUTTON | B_BUTTON | DPAD_ANY))
          {
              ClearBottomWindow();
              if (sInPartyMenu)
              {
                  CompactPartySlots();
                  CompactPartySprites();
                  sStorage.state++;
              }
              else
              {
                  sStorage.state = 7;
              }
          }
          break;
      case 6:
          if (GetNumPartySpritesCompacting() == 0)
          {
              RefreshDisplayMon();
              StartDisplayMonMosaicEffect();
              UpdatePartySlotColors();
              sStorage.state++;
          }
          break;
      case 7:
          SetPokeStorageTask(Task_PokeStorageMain);
          break;
      case 8:
           
          PrintMessage(MSG_WAS_RELEASED);
          sStorage.state++;
          break;
      case 9:
          if (JOY_NEW(A_BUTTON | B_BUTTON | DPAD_ANY))
          {
              PrintMessage(MSG_SURPRISE);
              sStorage.state++;
          }
          break;
      case 10:
          if (JOY_NEW(A_BUTTON | B_BUTTON | DPAD_ANY))
          {
              ClearBottomWindow();
              ReshowReleaseMon();
              sStorage.state++;
          }
          break;
      case 11:
          if (!ResetReleaseMonSpritePtr())
          {
              TrySetCursorFistAnim();
              PrintMessage(MSG_CAME_BACK);
              sStorage.state++;
          }
          break;
      case 12:
          if (JOY_NEW(A_BUTTON | B_BUTTON | DPAD_ANY))
          {
              PrintMessage(MSG_WORRIED);
              sStorage.state++;
          }
          break;
      case 13:
          if (JOY_NEW(A_BUTTON | B_BUTTON | DPAD_ANY))
          {
              ClearBottomWindow();
              SetPokeStorageTask(Task_PokeStorageMain);
          }
          break;
      }
};

