/** Source: pokemon_storage_system.c → Task_HandleWallpapers */
export const Task_HandleWallpapers: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  switch (sStorage.state)
      {
      case 0:
          AddWallpaperSetsMenu();
          PrintMessage(MSG_PICK_A_THEME);
          sStorage.state++;
          break;
      case 1:
          if (!IsMenuLoading())
               sStorage.state++;
          break;
      case 2:
          sStorage.wallpaperSetId = HandleMenuInput();
          switch (sStorage.wallpaperSetId)
          {
          case MENU_B_PRESSED:
              AnimateBoxScrollArrows(true);
              ClearBottomWindow();
              SetPokeStorageTask(Task_PokeStorageMain);
              break;
          case MENU_SCENERY_1:
          case MENU_SCENERY_2:
          case MENU_SCENERY_3:
          case MENU_ETCETERA:
              PlaySE(SE_SELECT);
              RemoveMenu();
              sStorage.wallpaperSetId -= MENU_WALLPAPER_SETS_START;
              sStorage.state++;
              break;
          case MENU_FRIENDS:
               
              PlaySE(SE_SELECT);
              sStorage.wallpaperId = WALLPAPER_FRIENDS;
              RemoveMenu();
              ClearBottomWindow();
              sStorage.state = 6;
              break;
          }
          break;
      case 3:
          if (!IsDma3ManagerBusyWithBgCopy())
          {
              AddWallpapersMenu(sStorage.wallpaperSetId);
              PrintMessage(MSG_PICK_A_WALLPAPER);
              sStorage.state++;
          }
          break;
      case 4:
          sStorage.wallpaperId = HandleMenuInput();
          switch (sStorage.wallpaperId)
          {
          case MENU_NOTHING_CHOSEN:
              break;
          case MENU_B_PRESSED:
              ClearBottomWindow();
              sStorage.state = 0;
              break;
          default:
              PlaySE(SE_SELECT);
              ClearBottomWindow();
              sStorage.wallpaperId -= MENU_WALLPAPERS_START;
              SetWallpaperForCurrentBox(sStorage.wallpaperId);
              sStorage.state++;
              break;
          }
          break;
      case 5:
          if (!DoWallpaperGfxChange())
          {
              AnimateBoxScrollArrows(true);
              SetPokeStorageTask(Task_PokeStorageMain);
          }
          break;
      case 6:
          if (!IsDma3ManagerBusyWithBgCopy())
          {
              SetWallpaperForCurrentBox(sStorage.wallpaperId);
              sStorage.state = 5;
          }
          break;
      }
};

