/** Source: pokemon_storage_system.c → Task_ChangeScreen */
export const Task_ChangeScreen: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let boxMons: any = null;
      let mode, monIndex, maxMonIndex;
      let screenChangeType = sStorage.screenChangeType;

      if (sStorage.boxOption == OPTION_MOVE_ITEMS && IsMovingItem() == true)
          sMovingItemId = GetMovingItemId();
      else
          sMovingItemId = ITEM_NONE;

      switch (screenChangeType)
      {
      case SCREEN_CHANGE_EXIT_BOX:
      default:
          FreePokeStorageData();
          rt.SetMainCallback2(CB2_ExitPokeStorage);
          break;
      case SCREEN_CHANGE_SUMMARY_SCREEN:
          boxMons = sStorage.summaryMon.box;
          monIndex = sStorage.summaryStartPos;
          maxMonIndex = sStorage.summaryMaxPos;
          mode = sStorage.summaryScreenMode;
          FreePokeStorageData();
          if (mode == SUMMARY_MODE_NORMAL && boxMons == sSavedMovingMon.box)
              ShowPokemonSummaryScreenHandleDeoxys(mode, boxMons, monIndex, maxMonIndex, CB2_ReturnToPokeStorage);
          else
              ShowPokemonSummaryScreen(mode, boxMons, monIndex, maxMonIndex, CB2_ReturnToPokeStorage);
          break;
      case SCREEN_CHANGE_NAME_BOX:
          FreePokeStorageData();
          DoNamingScreen(NAMING_SCREEN_BOX, GetBoxNamePtr(StorageGetCurrentBox()), 0, 0, 0, CB2_ReturnToPokeStorage);
          break;
      case SCREEN_CHANGE_ITEM_FROM_BAG:
          FreePokeStorageData();
          GoToBagMenu(ITEMMENULOCATION_PCBOX, 0, CB2_ReturnToPokeStorage);
          break;
      }

      rt.DestroyTask(taskId);
};

/** Source: pokemon_storage_system.c → Task_InitBox */
export const Task_InitBox: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  /* task already param */
      switch (task.data[0])
      {
      case 0:
          sStorage.wallpaperOffset = 0;
          sStorage.bg2_X = 0;
          task.data[1] = RequestDma3Fill(0, sStorage.wallpaperBgTilemapBuffer, 0, 1);
          break;
      case 1:
          if (CheckForSpaceForDma3Request(task.data[1]) == -1)
              return;

          SetBgTilemapBuffer(2, sStorage.wallpaperBgTilemapBuffer);
          ShowBg(2);
          break;
      case 2:
          LoadWallpaperGfx(task.data[2], 0);
          break;
      case 3:
          if (!WaitForWallpaperGfxLoad())
              return;

          InitBoxTitle(task.data[2]);
          CreateBoxScrollArrows();
          InitBoxMonSprites(task.data[2]);
          rt.SetGpuReg(REG_OFFSET_BG2CNT, BGCNT_PRIORITY(2) | BGCNT_CHARBASE(2) | BGCNT_SCREENBASE(27) | BGCNT_TXT512x256);
          break;
      case 4:
          rt.DestroyTask(taskId);
          break;
      default:
          task.data[0] = 0;
          return;
      }

      task.data[0]++;
};

