export const CB2_PokeStorage: CB2Callback = (rt) => {
  RunTasks();
      DoScheduledBgTilemapCopiesToVram();
      ScrollBackground();
      UpdateCloseBoxButtonFlash();
      AnimateSprites();
      BuildOamBuffer();
};

/** Source: pokemon_storage_system.c → CB2_ReturnToPokeStorage */
export const CB2_ReturnToPokeStorage: CB2Callback = (rt) => {
  ResetTasks();
      sStorage = Alloc(((sStorage)?.length ?? 32));
      if (sStorage == null)
      {
          rt.SetMainCallback2(CB2_ExitPokeStorage);
      }
      else
      {
          sStorage.boxOption = sCurrentBoxOption;
          sStorage.isReopening = true;
          sStorage.state = 0;
          sStorage.taskId = rt.CreateTask((t) => Task_InitPokeStorage(t, rt), 3);
          rt.SetMainCallback2(CB2_PokeStorage);
      }
};

